content.content:
/**
 * Decides whether a device should be given a WebGL scene at all.
 *
 * Every 3D surface on this site is decoration layered over content that
 * already works, so the bar for mounting one is deliberately high: a real GL
 * context, a pointer device, a wide viewport, enough cores, and no
 * reduced-motion preference (CLAUDE.md §7).
 */

/**
 * Actually creates a context rather than sniffing for support. Browsers report
 * WebGL as available in situations where context creation still fails —
 * blocklisted drivers, exhausted context limits, headless environments — and a
 * canvas that mounts without a context is worse than no canvas at all.
 */
export function hasWebGL(): boolean {
  if (typeof window === "undefined") return false;

  try {
    const canvas = document.createElement("canvas");
    const gl =
      canvas.getContext("webgl2") ??
      canvas.getContext("webgl") ??
      canvas.getContext("experimental-webgl");

    if (!gl) return false;

    // Release the probe context immediately; browsers cap how many can exist.
    const lose = (gl as WebGLRenderingContext).getExtension("WEBGL_lose_context");
    lose?.loseContext();

    return true;
  } catch {
    return false;
  }
}

/** True when the device looks too small or too weak to be worth the GPU cost. */
export function isLowCapabilityDevice(): boolean {
  if (typeof window === "undefined") return true;

  const coarse = window.matchMedia("(pointer: coarse)").matches;
  const narrow = window.matchMedia("(max-width: 1023px)").matches;

  // deviceMemory is Chromium-only; its absence is not evidence of weakness.
  const memory = (navigator as { deviceMemory?: number }).deviceMemory;
  const lowMemory = memory !== undefined && memory < 4;
  const fewCores = navigator.hardwareConcurrency < 4;

  return coarse || narrow || lowMemory || fewCores;
}

/** The full gate. `reducedMotion` comes from the app-wide provider. */
export function shouldRenderWebGL(reducedMotion: boolean): boolean {
  return !reducedMotion && !isLowCapabilityDevice() && hasWebGL();
}
=====LENIS
"use client";

import { useEffect } from "react";
import Lenis from "lenis";
import "lenis/dist/lenis.css";

import { useReducedMotionPreference } from "@/components/providers/reduced-motion-provider";

/**
 * Weighted smooth scroll — the single cheapest signal that a site was built
 * rather than assembled.
 *
 * Deliberately skipped on two paths: when the visitor asks for reduced motion,
 * and on coarse pointers, where hijacking native momentum scroll costs INP on
 * the low-end Android hardware much of this audience browses on (CLAUDE.md §6).
 */
export function LenisProvider() {
  const reducedMotion = useReducedMotionPreference();

  useEffect(() => {
    if (reducedMotion) return;

    const isTouch = window.matchMedia("(pointer: coarse)").matches;
    if (isTouch) return;

    const lenis = new Lenis({ lerp: 0.1, wheelMultiplier: 1 });

    let frame = 0;
    const raf = (time: number) => {
      lenis.raf(time);
      frame = requestAnimationFrame(raf);
    };
    frame = requestAnimationFrame(raf);

    return () => {
      cancelAnimationFrame(frame);
      lenis.destroy();
    };
  }, [reducedMotion]);

  return null;
}
=====RM
"use client";

import { createContext, useCallback, useContext, useSyncExternalStore } from "react";

const ReducedMotionContext = createContext(false);

const QUERY = "(prefers-reduced-motion: reduce)";

/**
 * Single source of truth for `prefers-reduced-motion`.
 *
 * Every motion decision in the app reads this: Lenis stays off, GSAP degrades
 * to fades, and the WebGL hero swaps for a static image. CSS handles its own
 * half via the media query in globals.css; this covers the JS half.
 *
 * Read through `useSyncExternalStore` rather than an effect, so the value is
 * correct on the first client render — no flash of motion before the
 * preference is detected.
 */
export function ReducedMotionProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const reduced = useReducedMotionQuery();

  return (
    <ReducedMotionContext.Provider value={reduced}>
      {children}
    </ReducedMotionContext.Provider>
  );
}

function useReducedMotionQuery(): boolean {
  const subscribe = useCallback((onChange: () => void) => {
    const query = window.matchMedia(QUERY);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);

  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(QUERY).matches,
    // Server snapshot: assume motion is allowed, then correct on hydration.
    () => false,
  );
}

/** Read the visitor's motion preference from any client component. */
export function useReducedMotionPreference(): boolean {
  return useContext(ReducedMotionContext);
